CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, apple_sub TEXT UNIQUE NOT NULL, name TEXT NOT NULL, level REAL NOT NULL DEFAULT 3.5, area TEXT NOT NULL DEFAULT 'Westside', refresh_token TEXT, terms_version TEXT NOT NULL, created_at BIGINT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (digest TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, nonce TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, court_id TEXT NOT NULL, start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, level_min REAL NOT NULL, level_max REAL NOT NULL, format TEXT NOT NULL, court_booked INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS requests_search ON requests(status, start_at, end_at, court_id);
CREATE TABLE IF NOT EXISTS interests (request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', created_at BIGINT NOT NULL, PRIMARY KEY (request_id,user_id));
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, request_id TEXT NOT NULL UNIQUE REFERENCES requests(id) ON DELETE CASCADE, host_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, guest_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, active INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS message_cursor ON messages(conversation_id, created_at, id);
CREATE TABLE IF NOT EXISTS blocks (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,blocked_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id TEXT REFERENCES users(id) ON DELETE SET NULL, subject_id TEXT REFERENCES users(id) ON DELETE SET NULL, message_id TEXT, reason TEXT NOT NULL, created_at BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS devices (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, environment TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, quiet_hours INTEGER NOT NULL DEFAULT 1, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS entitlements (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, original_id TEXT UNIQUE NOT NULL, product_id TEXT NOT NULL, expires_at BIGINT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, signed_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS watches (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, court_id TEXT NOT NULL, start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, duration INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (key TEXT PRIMARY KEY, court_id TEXT NOT NULL, date TEXT NOT NULL, checked_at BIGINT NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, source_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alert_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, ref_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created_at BIGINT NOT NULL, read_at BIGINT);
CREATE INDEX IF NOT EXISTS inbox_cursor ON alert_events(user_id,created_at);
CREATE TABLE IF NOT EXISTS deliveries (event_id TEXT NOT NULL REFERENCES alert_events(id) ON DELETE CASCADE, token TEXT NOT NULL REFERENCES devices(token) ON DELETE CASCADE, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at BIGINT NOT NULL, lease_until BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(event_id,token));
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at BIGINT NOT NULL);
